{"kind": "content", "icon": "🏦", "head": "व्यावसायिक बैंक", "points": ["जमा स्वीकार करना", "ऋण देना", "बचत, चालू, सावधि खाता", "ब्याज का अंतर ही लाभ"], "say": "व्यावसायिक बैंक वह संस्था है जो लोगों से जमा लेती है और ज़रूरतमंद लोगों व व्यवसायों को उधार देती है। जमा के तीन मुख्य प्रकार हैं। बचत खाता, जिसमें आम लोग पैसा रखते हैं और थोड़ा ब्याज पाते हैं। चालू खाता, जो व्यापारियों के लिए है, जिसमें दिन में कई बार लेन-देन हो सकता है। और सावधि जमा, यानी फ़िक्स्ड डिपॉज़िट, जिसमें एक तय समय के लिए पैसा रखते हैं और ज़्यादा ब्याज मिलता है। बैंक कम ब्याज पर जमा लेकर ज़्यादा ब्याज पर उधार देता है, यही अंतर उसका लाभ है।", "ext": 1},
{"kind": "content", "icon": "🔄", "head": "साख सृजन कैसे होता है", "points": ["लोग सारा पैसा एक साथ नहीं निकालते", "कुछ हिस्सा रिज़र्व", "बाकी उधार", "उधार फिर जमा बनता है"], "say": "बैंक पैसा कैसे बनाता है, यह समझिए। बैंक जानता है कि सब जमाकर्ता एक साथ अपना पूरा पैसा नहीं निकालेंगे। इसलिए वह जमा का कुछ हिस्सा, मान लीजिए बीस प्रतिशत, नकद रिज़र्व में रखता है और बाकी अस्सी प्रतिशत उधार दे देता है। जिसे उधार मिला, वह उस पैसे से सामान खरीदता है, और दुकानदार वह पैसा फिर किसी बैंक में जमा कर देता है। बैंक फिर उसका अस्सी प्रतिशत उधार देता है। यह चक्र चलता रहता है और शुरुआती जमा से कई गुना ज़्यादा जमा बन जाती है।", "ext": 1},
{"kind": "table", "icon": "✖️", "head": "मुद्रा गुणक का सूत्र", "eq": "सूत्र", "rows": [["मुद्रा गुणक", "1 ÷ रिज़र्व अनुपात"], ["कुल साख", "प्रारंभिक जमा × गुणक"], ["उदाहरण", "1000 × (1 ÷ 0.2) = 5000"]], "say": "साख सृजन को सूत्र से नापते हैं। मुद्रा गुणक बराबर एक भाग रिज़र्व अनुपात। अगर रिज़र्व अनुपात बीस प्रतिशत यानी शून्य दशमलव दो है, तो गुणक बराबर एक भाग शून्य दशमलव दो, यानी पाँच। अब अगर किसी ने एक हज़ार रुपये जमा किए, तो कुल जमा बनेगी एक हज़ार गुणा पाँच, यानी पाँच हज़ार रुपये। इसमें एक हज़ार की शुरुआती जमा है और चार हज़ार की नई साख बनी। ध्यान रखिए, रिज़र्व अनुपात जितना कम, गुणक उतना बड़ा।", "ext": 1},
{"kind": "content", "icon": "🏛️", "head": "केंद्रीय बैंक के कार्य", "points": ["नोट छापना", "सरकार का बैंक", "बैंकों का बैंक", "अंतिम ऋणदाता", "साख नियंत्रण", "विदेशी मुद्रा का रखवाला"], "say": "भारत का केंद्रीय बैंक भारतीय रिज़र्व बैंक है, जो उन्नीस सौ पैंतीस में बना। इसके मुख्य कार्य हैं। यह नोट छापता है, एक रुपये के नोट और सिक्कों को छोड़कर, जो सरकार बनाती है। यह सरकार का बैंक है, सरकार का खाता रखता है और उसे सलाह देता है। यह बैंकों का बैंक है, सभी बैंक इसमें अपना रिज़र्व रखते हैं। मुसीबत में बैंकों को उधार देता है, इसलिए अंतिम ऋणदाता है। यह देश में साख यानी उधार की मात्रा नियंत्रित करता है। और विदेशी मुद्रा भंडार का रखवाला है।", "ext": 1},
{"kind": "table", "icon": "🎛️", "head": "साख नियंत्रण के उपकरण", "eq": "उपकरण", "rows": [["रेपो दर", "RBI से बैंकों को उधार की दर"], ["रिवर्स रेपो दर", "बैंक RBI में पैसा रखें तो दर"], ["नकद आरक्षित अनुपात", "बैंक RBI में नकद रखें"], ["वैधानिक तरलता अनुपात", "बैंक अपने पास तरल संपत्ति रखें"], ["खुले बाज़ार की क्रियाएँ", "सरकारी बॉन्ड खरीदना-बेचना"]], "say": "रिज़र्व बैंक उधार की मात्रा कई उपकरणों से नियंत्रित करता है। रेपो दर वह ब्याज दर है जिस पर रिज़र्व बैंक दूसरे बैंकों को उधार देता है। रिवर्स रेपो दर पर बैंक अपना अतिरिक्त पैसा रिज़र्व बैंक में रखते हैं। नकद आरक्षित अनुपात यानी सी आर आर, बैंकों को अपनी जमा का कितना हिस्सा रिज़र्व बैंक में नकद रखना है। वैधानिक तरलता अनुपात यानी एस एल आर, बैंकों को अपने पास कितनी तरल संपत्ति रखनी है। और खुले बाज़ार की क्रियाएँ, यानी सरकारी बॉन्ड खरीदना या बेचना।", "ext": 1},
{"kind": "content", "icon": "🌡️", "head": "महँगाई में रिज़र्व बैंक क्या करता है", "points": ["रेपो दर बढ़ाता", "सी आर आर बढ़ाता", "बॉन्ड बेचता", "उधार महँगा, पैसा कम"], "say": "जब देश में महँगाई बढ़ती है, यानी बाज़ार में पैसा ज़्यादा और सामान कम है, तो रिज़र्व बैंक बाज़ार से पैसा कम करना चाहता है। इसके लिए वह रेपो दर बढ़ाता है, जिससे बैंकों के लिए उधार महँगा होता है, और वे भी लोगों को महँगी दर पर उधार देते हैं, तो लोग कम उधार लेते हैं। वह सी आर आर बढ़ाता है, जिससे बैंकों के पास उधार देने को कम पैसा बचता है। और वह खुले बाज़ार में बॉन्ड बेचता है, जिससे लोगों का पैसा रिज़र्व बैंक के पास आ जाता है। मंदी में इसका ठीक उल्टा करता है।", "ext": 1},
{"kind": "question", "icon": "🤔", "head": "सोचिए", "q": "रिज़र्व अनुपात 10% है और प्रारंभिक जमा ₹2000। कुल जमा कितनी बनेगी?", "a": "₹20,000 (गुणक = 1 ÷ 0.1 = 10)", "pause": 4, "say": "एक सवाल हल कीजिए। अगर रिज़र्व अनुपात दस प्रतिशत है और किसी ने दो हज़ार रुपये बैंक में जमा किए, तो कुल कितनी जमा बनेगी? रुककर हल कीजिए। पहले गुणक निकालिए, एक भाग शून्य दशमलव एक, यानी दस। फिर कुल जमा बराबर दो हज़ार गुणा दस, यानी बीस हज़ार रुपये। इनमें अठारह हज़ार रुपये की नई साख बनी।", "ext": 1},
{"kind": "content", "icon": "💵", "head": "मुद्रा के प्रकार", "points": ["सिक्के और नोट: करेंसी", "कागज़ी मुद्रा: फ़िएट", "माँग जमा: चेक से", "डिजिटल: यूपीआई, कार्ड", "डिजिटल रुपया (e₹)"], "say": "मुद्रा कई रूपों में होती है। सिक्के और नोट, जिन्हें करेंसी कहते हैं। आज के नोट फ़िएट मुद्रा हैं, यानी इनकी कीमत इनके काग़ज़ में नहीं, बल्कि सरकार की गारंटी में है, इसीलिए नोट पर लिखा होता है, मैं धारक को इतने रुपये अदा करने का वचन देता हूँ, और रिज़र्व बैंक के गवर्नर के हस्ताक्षर होते हैं। बैंक में माँग जमा भी मुद्रा है, जिसे चेक से कभी भी निकाला जा सकता है। आज यू पी आई, डेबिट और क्रेडिट कार्ड से डिजिटल भुगतान बहुत बढ़ा है। रिज़र्व बैंक ने डिजिटल रुपया भी शुरू किया है।", "ext": 5},
{"kind": "table", "icon": "📊", "head": "मुद्रा पूर्ति के माप", "eq": "माप", "rows": [["M⁠1", "जनता के पास करेंसी + बैंकों में माँग जमा + RBI के पास अन्य जमा"], ["M⁠2", "M⁠1 + डाकघर बचत जमा"], ["M⁠3", "M⁠1 + बैंकों में सावधि जमा (व्यापक मुद्रा)"], ["M⁠4", "M⁠3 + डाकघर की कुल जमा"]], "say": "रिज़र्व बैंक मुद्रा की पूर्ति को चार तरह से मापता है। एम वन सबसे तरल है, जिसमें जनता के पास नोट और सिक्के, बैंकों में माँग जमा, और रिज़र्व बैंक के पास दूसरी जमाएँ आती हैं, इसे संकीर्ण मुद्रा भी कहते हैं। एम टू में एम वन के साथ डाकघर की बचत जमा जुड़ती है। एम थ्री में एम वन के साथ बैंकों की सावधि जमा जुड़ती है, इसे व्यापक मुद्रा कहते हैं, और यह सबसे ज़्यादा इस्तेमाल होने वाला माप है। एम फ़ोर में एम थ्री के साथ डाकघर की कुल जमा जुड़ती है। एम वन से एम फ़ोर की ओर तरलता घटती है।", "ext": 5},
{"kind": "content", "icon": "🏦", "head": "व्यावसायिक बैंकों के अन्य कार्य", "points": ["चेक, ड्राफ़्ट से पैसा भेजना", "लॉकर", "एटीएम, नेट बैंकिंग", "बिलों का भुगतान", "सरकारी योजनाओं का पैसा: डीबीटी"], "say": "जमा लेने और ऋण देने के अलावा, बैंक कई और काम करते हैं। चेक, डिमांड ड्राफ़्ट और ऑनलाइन ट्रांसफ़र से पैसा एक जगह से दूसरी जगह भेजते हैं। क़ीमती सामान रखने के लिए लॉकर की सुविधा देते हैं। ए टी एम, नेट बैंकिंग और मोबाइल बैंकिंग से चौबीस घंटे सेवा देते हैं। बिजली, पानी, बीमा के बिलों का भुगतान करते हैं। और सरकार की योजनाओं का पैसा, जैसे छात्रवृत्ति, पेंशन और किसान सम्मान निधि, सीधे लाभार्थी के खाते में पहुँचाते हैं, इसे प्रत्यक्ष लाभ हस्तांतरण कहते हैं। जन धन योजना से करोड़ों ग़रीबों के बैंक खाते खुले।", "ext": 5},
{"kind": "content", "icon": "🔁", "head": "ऋण के प्रकार", "points": ["नकद साख", "अधिविकर्ष (ओवरड्राफ़्ट)", "माँग ऋण, सावधि ऋण", "बिलों की कटौती", "किसान क्रेडिट कार्ड"], "say": "बैंक कई तरह के ऋण देते हैं। नकद साख, जिसमें व्यापारी को एक सीमा तक पैसा निकालने की छूट मिलती है, और सिर्फ़ निकाले गए पैसे पर ब्याज लगता है। अधिविकर्ष, यानी ओवरड्राफ़्ट, जिसमें चालू खाते वाला ग्राहक अपनी जमा से ज़्यादा पैसा निकाल सकता है। माँग ऋण, जो बैंक कभी भी वापस माँग सकता है, और सावधि ऋण, जो तय समय के लिए होता है, जैसे घर या गाड़ी का ऋण। व्यापारिक बिलों की कटौती, यानी बिल की तारीख़ से पहले पैसा देना। और किसानों के लिए किसान क्रेडिट कार्ड, जिससे उन्हें कम ब्याज पर खेती का ऋण मिलता है।", "ext": 5},
{"kind": "content", "icon": "📉", "head": "विमुद्रीकरण और मुद्रा", "points": ["नवंबर 2016", "500, 1000 के नोट बंद", "नकदी कम, डिजिटल बढ़ा", "बैंकों में जमा बढ़ी", "कुछ समय की परेशानी"], "say": "नवंबर दो हज़ार सोलह में सरकार ने पाँच सौ और एक हज़ार के पुराने नोट बंद कर दिए, जो उस समय चलन में मौजूद करेंसी का बड़ा हिस्सा थे। लोगों को पुराने नोट बैंकों में जमा करने पड़े। इससे कुछ समय के लिए बाज़ार में नकदी की भारी कमी हुई, और छोटे व्यापारियों, मज़दूरों और किसानों को परेशानी हुई। पर बैंकों में जमा बहुत बढ़ गई, और डिजिटल भुगतान तेज़ी से बढ़ा। इसके उद्देश्य काला धन और नकली नोट रोकना बताए गए थे, इसके परिणामों पर अर्थशास्त्रियों की अलग-अलग राय है।", "ext": 5},
